#!/usr/bin/env bash
# Direct focal test: DPVO on the 8 flir-VIS dev clips with VGGT-1B per-clip focal scale (raw, no bias
# correction), seeds 0-2. One output dir per clip (run_dpvo locks one focal scale per dir), merged per seed.
# Start: setsid nohup bash fermarble/jobs/vggt_focal_dpvo.sh > runs/vggt_focal_dpvo.log 2>&1 < /dev/null &
set -u
cd "$(dirname "$0")/../.."
PY=$HOME/micromamba/envs/dpvo/bin/python
echo "$(date '+%F %T') START"
( mkdir -p runs/fvggt/s0/clip_000 && $PY fermarble/run_dpvo.py --clips clip_000 --seed 0 --focal-scale 1.492 --output runs/fvggt/s0/clip_000 >> runs/fvggt/s0/clip_000/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_001 && $PY fermarble/run_dpvo.py --clips clip_001 --seed 0 --focal-scale 2.081 --output runs/fvggt/s0/clip_001 >> runs/fvggt/s0/clip_001/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_075 && $PY fermarble/run_dpvo.py --clips clip_075 --seed 0 --focal-scale 1.137 --output runs/fvggt/s0/clip_075 >> runs/fvggt/s0/clip_075/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_076 && $PY fermarble/run_dpvo.py --clips clip_076 --seed 0 --focal-scale 1.476 --output runs/fvggt/s0/clip_076 >> runs/fvggt/s0/clip_076/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_082 && $PY fermarble/run_dpvo.py --clips clip_082 --seed 0 --focal-scale 1.011 --output runs/fvggt/s0/clip_082 >> runs/fvggt/s0/clip_082/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_084 && $PY fermarble/run_dpvo.py --clips clip_084 --seed 0 --focal-scale 1.429 --output runs/fvggt/s0/clip_084 >> runs/fvggt/s0/clip_084/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_088 && $PY fermarble/run_dpvo.py --clips clip_088 --seed 0 --focal-scale 1.433 --output runs/fvggt/s0/clip_088 >> runs/fvggt/s0/clip_088/run.log 2>&1 ; mkdir -p runs/fvggt/s0/clip_090 && $PY fermarble/run_dpvo.py --clips clip_090 --seed 0 --focal-scale 1.384 --output runs/fvggt/s0/clip_090 >> runs/fvggt/s0/clip_090/run.log 2>&1 ) &
( mkdir -p runs/fvggt/s1/clip_000 && $PY fermarble/run_dpvo.py --clips clip_000 --seed 1 --focal-scale 1.492 --output runs/fvggt/s1/clip_000 >> runs/fvggt/s1/clip_000/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_001 && $PY fermarble/run_dpvo.py --clips clip_001 --seed 1 --focal-scale 2.081 --output runs/fvggt/s1/clip_001 >> runs/fvggt/s1/clip_001/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_075 && $PY fermarble/run_dpvo.py --clips clip_075 --seed 1 --focal-scale 1.137 --output runs/fvggt/s1/clip_075 >> runs/fvggt/s1/clip_075/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_076 && $PY fermarble/run_dpvo.py --clips clip_076 --seed 1 --focal-scale 1.476 --output runs/fvggt/s1/clip_076 >> runs/fvggt/s1/clip_076/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_082 && $PY fermarble/run_dpvo.py --clips clip_082 --seed 1 --focal-scale 1.011 --output runs/fvggt/s1/clip_082 >> runs/fvggt/s1/clip_082/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_084 && $PY fermarble/run_dpvo.py --clips clip_084 --seed 1 --focal-scale 1.429 --output runs/fvggt/s1/clip_084 >> runs/fvggt/s1/clip_084/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_088 && $PY fermarble/run_dpvo.py --clips clip_088 --seed 1 --focal-scale 1.433 --output runs/fvggt/s1/clip_088 >> runs/fvggt/s1/clip_088/run.log 2>&1 ; mkdir -p runs/fvggt/s1/clip_090 && $PY fermarble/run_dpvo.py --clips clip_090 --seed 1 --focal-scale 1.384 --output runs/fvggt/s1/clip_090 >> runs/fvggt/s1/clip_090/run.log 2>&1 ) &
( mkdir -p runs/fvggt/s2/clip_000 && $PY fermarble/run_dpvo.py --clips clip_000 --seed 2 --focal-scale 1.492 --output runs/fvggt/s2/clip_000 >> runs/fvggt/s2/clip_000/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_001 && $PY fermarble/run_dpvo.py --clips clip_001 --seed 2 --focal-scale 2.081 --output runs/fvggt/s2/clip_001 >> runs/fvggt/s2/clip_001/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_075 && $PY fermarble/run_dpvo.py --clips clip_075 --seed 2 --focal-scale 1.137 --output runs/fvggt/s2/clip_075 >> runs/fvggt/s2/clip_075/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_076 && $PY fermarble/run_dpvo.py --clips clip_076 --seed 2 --focal-scale 1.476 --output runs/fvggt/s2/clip_076 >> runs/fvggt/s2/clip_076/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_082 && $PY fermarble/run_dpvo.py --clips clip_082 --seed 2 --focal-scale 1.011 --output runs/fvggt/s2/clip_082 >> runs/fvggt/s2/clip_082/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_084 && $PY fermarble/run_dpvo.py --clips clip_084 --seed 2 --focal-scale 1.429 --output runs/fvggt/s2/clip_084 >> runs/fvggt/s2/clip_084/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_088 && $PY fermarble/run_dpvo.py --clips clip_088 --seed 2 --focal-scale 1.433 --output runs/fvggt/s2/clip_088 >> runs/fvggt/s2/clip_088/run.log 2>&1 ; mkdir -p runs/fvggt/s2/clip_090 && $PY fermarble/run_dpvo.py --clips clip_090 --seed 2 --focal-scale 1.384 --output runs/fvggt/s2/clip_090 >> runs/fvggt/s2/clip_090/run.log 2>&1 ) &
wait
for s in 0 1 2; do d=runs/dpvo-fps8-seed$s-fvggt/poses; mkdir -p $d; for c in runs/fvggt/s$s/*/poses/*.npz; do ln -sfn ../../fvggt/s$s/$(basename $(dirname $(dirname $c)))/poses/$(basename $c) $d/; done; echo "seed $s: $(ls $d | wc -l)/8"; done
echo "$(date '+%F %T') DONE"
